mapper.select:
SELECT * FROM game_match
 WHERE tournament_id = #{tournamentId}
 ORDER BY round_no ASC, slot_no ASC

SELECT * FROM game_match
 WHERE tournament_id = #{tournamentId} AND stage = #{stage}
 ORDER BY round_no ASC, slot_no ASC

SELECT COUNT(*) FROM game_match
 WHERE tournament_id = #{tournamentId} AND stage = #{stage} AND round_no = #{roundNo}
   AND status IN ('FINISHED', 'BYE')

SELECT * FROM game_round
 WHERE status = 'REST' AND rest_until <= #{now}
 ORDER BY rest_until ASC

mapper.update:
UPDATE game_match
   SET first_game_id = #{gameId}
 WHERE id = #{matchId} AND status IN ('PENDING', 'READY')

UPDATE game_match
   SET status = 'FINISHED', winner_user_id = #{winnerUserId}, player1_score = #{player1Score},
       player2_score = #{player2Score}, finished_at = #{now}
 WHERE id = #{matchId}

UPDATE game_round
   SET status = 'REST', winner_user_id = #{winnerUserId}, rest_until = #{restUntil}
 WHERE id = #{roundId} AND status = 'RUNNING'

choose.when:
UPDATE game_match
   SET player1_user_id = #{userId}, player1_nickname = #{nickname}
 WHERE id = #{nextMatchId}

choose.otherwise:
UPDATE game_match
   SET player2_user_id = #{userId}, player2_nickname = #{nickname}
 WHERE id = #{nextMatchId}

mapper.select:
SELECT * FROM game_round
 WHERE status = 'RUNNING' AND game_id <> #{gomokuGameId}
 ORDER BY started_at ASC

mapper.update:
UPDATE game_round
   SET turn_user_id = #{nextTurnUserId}, move_count = #{nextCount}, last_move_at = #{now}
 WHERE id = #{roundId} AND move_count = #{expectedCount} AND status = 'RUNNING'

UPDATE game_round
   SET status = #{status}, winner_user_id = #{winnerUserId},
       rest_until = #{restUntil}, finished_at = #{finishedAt}
 WHERE id = #{roundId}

UPDATE game_round
   SET status = 'FINISHED', rest_until = NULL, finished_at = #{now}
 WHERE id = #{roundId} AND status = 'REST'

mapper.select:
SELECT m.id, m.tournament_id, m.round_no, m.slot_no, m.stage, m.status, m.player1_user_id, m.player1_nickname, m.player2_user_id, m.player2_nickname, m.player1_score, m.player2_score, m.winner_user_id, m.next_match_id, m.first_game_id, m.game_chooser_user_id, m.visible, m.display_order, m.managed_by, m.managed_at, m.created_at, m.started_at, m.finished_at FROM game_match m JOIN game_tournament t ON t.id = m.tournament_id WHERE t.deleted_at IS NULL AND t.kind = 'TOURNAMENT'
AND m.visible = 1
ORDER BY m.display_order DESC, m.created_at DESC LIMIT #{limit}

mapper.update:
UPDATE game_match

  visible = #{visible},
  display_order = #{displayOrder},
  managed_by = #{managedBy},
  managed_at = #{now}

 WHERE id = #{matchId}
